import zipfile
import xml.etree.ElementTree as ET

NS = {
    "m": "http://schemas.openxmlformats.org/spreadsheetml/2006/main",
    "r": "http://schemas.openxmlformats.org/officeDocument/2006/relationships",
    "rel": "http://schemas.openxmlformats.org/package/2006/relationships",
}

def q(tag):
    p, _, name = tag.partition("}")
    return name

def read_xlsx(path):
    with zipfile.ZipFile(path) as z:
        names = z.namelist()
        print("ZIP entries:", names)

        # shared strings
        shared = []
        if "xl/sharedStrings.xml" in names:
            root = ET.fromstring(z.read("xl/sharedStrings.xml"))
            for si in root.findall("m:si", NS):
                text = "".join(t.text or "" for t in si.iter() if q(t.tag) == "t")
                shared.append(text)

        # workbook -> sheet name / rId
        wb_root = ET.fromstring(z.read("xl/workbook.xml"))
        sheet_rid = {}
        for sh in wb_root.findall(".//m:sheet", NS):
            sheet_rid[sh.get("name")] = sh.get("{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id")

        # rels -> rId -> target path
        rels_root = ET.fromstring(z.read("xl/_rels/workbook.xml.rels"))
        rid_target = {}
        for rel in rels_root.findall("rel:Relationship", NS):
            rid_target[rel.get("Id")] = rel.get("Target")

        for name in wb_root.findall(".//m:sheet", NS):
            sheet_name = name.get("name")
            rid = sheet_rid[sheet_name]
            target = rid_target[rid]
            if not target.startswith("xl/"):
                target = "xl/" + target
            print(f"\n--- Sheet: {sheet_name} (file: {target}) ---")
            sroot = ET.fromstring(z.read(target))
            for row in sroot.iter("m:row", NS):
                for c in row.findall("m:c", NS):
                    ref = c.get("r")
                    t = c.get("t", "n")
                    v = c.find("m:v", NS)
                    isel = c.find("m:is", NS)
                    raw = None
                    if t == "s" and v is not None:
                        raw = shared[int(v.text)]
                    elif t == "inlineStr" and isel is not None:
                        raw = "".join(x.text or "" for x in isel.iter() if q(x.tag) == "t")
                    elif v is not None:
                        raw = v.text
                    if raw is not None:
                        print(f"{ref}: {raw!r}")

read_xlsx("budget.xlsx")

